                        <div className="rounded-2xl bg-white shadow-sm border border-slate-100 p-6 text-center">
                            <p className="text-xs text-slate-400">Loading...</p>
                        </div>
                        <div className="rounded-2xl bg-white shadow-sm border border-slate-100 p-6 text-center">
                            <p className="text-xs text-slate-400">Loading...</p>
                        </div>
